window.googleProvider = new firebase.auth.GoogleAuthProvider();
window.googleProvider.addScope('profile');
window.googleProvider.addScope('email');

// Argentina es UTC-3: usar toISOString() para obtener "el día de hoy" o el día de
// una fecha guardada rompe el cálculo entre ~21:00 y 00:00 hora local, porque
// toISOString() convierte a UTC y ese horario ya cae en el día siguiente en UTC.
// Estas dos funciones son la forma correcta y única que debe usarse en todo el
// proyecto para trabajar con "día calendario": nunca con toISOString().
function obtenerAhoraArgentina() {
    return new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Argentina/Buenos_Aires' }));
}

function formatearFechaLocal(fecha) {
    const y = fecha.getFullYear();
    const m = String(fecha.getMonth() + 1).padStart(2, '0');
    const d = String(fecha.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
}

// "new Date('YYYY-MM-DD').getDay()" se parsea como medianoche UTC, que en
// Argentina (UTC-3) ya es el día anterior a las 21hs — el día de la semana
// queda sistemáticamente mal calculado. Construir el Date con año/mes/día
// como componentes locales evita el problema por completo.
function obtenerDiaSemanaDeFechaStr(fechaStr) {
    const [y, m, d] = fechaStr.split('-').map(Number);
    return new Date(y, m - 1, d).getDay();
}

// Par inverso de formatearFechaLocal(): arma un Date a medianoche local a
// partir de un string "YYYY-MM-DD", sin pasar por el parseo ambiguo de
// new Date(string) (que interpreta según el timezone del navegador y con
// frecuencia calcula mal el día). Usar siempre esto en vez de
// `new Date(fechaStr + 'T03:00:00')` — ese patrón asume que se parsea como
// UTC, pero en realidad se parsea en hora local del navegador.
function parsearFechaLocal(fechaStr) {
    const [y, m, d] = fechaStr.split('-').map(Number);
    return new Date(y, m - 1, d);
}

// Horas (puede dar negativo si ya pasó) entre ahora y un turno dado por
// fecha "YYYY-MM-DD" + horario "HH:MM". Usado tanto para decidir si un
// turno todavía se puede cancelar (regla de 24hs) como para no mostrar
// el botón de cancelar cuando ya no aplica.
function horasHastaFechaHora(fechaStr, horaStr) {
    const [hora, minuto] = horaStr.split(':').map(Number);
    const [y, m, d] = fechaStr.split('-').map(Number);
    const inicio = new Date(y, m - 1, d, hora, minuto);
    return (inicio.getTime() - Date.now()) / (1000 * 60 * 60);
}

// Multi-tenant: a qué negocio pertenecen los datos que hay que leer/escribir.
// En producción cada negocio vive en su propio subdominio
// (negocio.gestionturno.com), así que el subdominio ES el negocioId. En
// desarrollo local (localhost) o en el dominio raíz sin subdominio todavía
// no hay resolución real de subdominio (eso es una fase aparte, pendiente,
// ver docs/arquitectura-multi-tenant.md) — se usa el negocio piloto/demo
// como valor por defecto para que el desarrollo y las pruebas no se rompan.
const NEGOCIO_ID_DEFAULT = 'demopro';

function obtenerNegocioIdActual() {
    const host = window.location.hostname;
    const partes = host.split('.');

    if (partes.length < 3 || partes[0] === 'www') {
        // Solo para desarrollo local: permite forzar un negocio distinto
        // al de muestra sin necesidad de un subdominio real (útil para
        // probar flujos como el pago). Nunca pisa la resolución de un
        // subdominio real — solo aplica cuando ya se cayó al default.
        // Para activar: localStorage.setItem('negocioIdOverrideDev', 'slug')
        // Para volver a demopro: localStorage.removeItem('negocioIdOverrideDev')
        const override = localStorage.getItem('negocioIdOverrideDev');
        if (override) return override;
        return NEGOCIO_ID_DEFAULT;
    }

    return partes[0];
}