// Al redirigir a Mercado Pago con window.location.href, la página queda
// "congelada" en memoria (bfcache) en el estado exacto en el que estaba
// justo antes de irse — loader de "reservando" incluido. Si el cliente
// vuelve con el botón atrás del navegador en vez de completar el pago, el
// navegador restaura esa página congelada tal cual (no vuelve a ejecutar
// el script desde cero), así que el loader queda visible para siempre sin
// que nada lo saque de ahí. pageshow con persisted:true detecta ese caso
// y fuerza una recarga real, que sí vuelve a correr la inicialización
// normal de la página.
window.addEventListener('pageshow', (event) => {
    if (event.persisted) {
        location.reload();
    }
});

