// Wrap seguro para funciones de Firestore
const firestoreSeguro = {
  obtenerCategorias: async () => {
        try {
            if (cache.esValido('categorias')) {
                return cache.obtener('categorias');
            }
            
            const categorias = await firestoreDB.obtenerCategorias();
            cache.guardar('categorias', categorias);
            return categorias;
        } catch (error) {
            return ErrorHandler.manejarErrorFirestore(error, 'cargar categorías');
        }
    },
  
  obtenerServicios: async () => {
        try {
            if (cache.esValido('servicios')) {
                return cache.obtener('servicios');
            }
            
            const servicios = await firestoreDB.obtenerServicios();
            cache.guardar('servicios', servicios);
            return servicios;
        } catch (error) {
            return ErrorHandler.manejarErrorFirestore(error, 'cargar servicios');
        }
    },

    obtenerEspecialistasPorCategoria: async (categoriaId) => {
        try {
            if (cache.esValido('especialistas', categoriaId)) {
                const cached = cache.obtener('especialistas', categoriaId);
                // ✅ CORRECCIÓN: Verificar que el caché no sea un array vacío incorrecto
                if (cached && Array.isArray(cached) && cached.length > 0) {
                    return cached;
                } else {
                    // Si el caché está vacío o es inválido, forzar recarga
                    cache.limpiarEspecifico('especialistas', categoriaId);
                }
            }
            
            const especialistas = await firestoreDB.obtenerEspecialistasPorCategoria(categoriaId);
            
            // ✅ CORRECCIÓN: Guardar en caché solo si hay especialistas reales
            if (especialistas && Array.isArray(especialistas) && especialistas.length > 0) {
                cache.guardar('especialistas', especialistas, categoriaId);
            } else {
                // No guardar arrays vacíos en caché para evitar problemas
                console.warn(`⚠️ No se guardará caché vacío para categoría ${categoriaId}`);
            }
            
            return especialistas || [];
        } catch (error) {
            console.error(`❌ Error obteniendo especialistas para categoría ${categoriaId}:`, error);
            // ✅ Siempre devolver un array vacío en caso de error
            return [];
        }
    },
    
  // Sin caché a propósito: es un solo documento (lectura barata) y trae
  // campos que necesitan reflejarse al instante en cuanto el superadmin
  // los cambia — pagoOnlineActivo en particular. Cachearlo (como se hacía
  // antes, hasta 5 min en memoria / 1 hora en localStorage) hacía que
  // activar el cobro de un negocio pareciera "no funcionar" durante ese
  // rato, sin ningún error visible.
  obtenerConfiguracion: async () => {
        try {
            const config = await firestoreDB.obtenerConfiguracion();
            return config;
        } catch (error) {
            ErrorHandler.manejarErrorFirestore(error, 'cargar configuración');
            // Retornar configuración por defecto
            return {
                diasLaborales: [1, 2, 3, 4, 5, 6],
                horarioApertura: "09:00",
                horarioCierre: "20:00",
                duracionTurnoBase: 30
            };
        }
    },

  verificarDisponibilidad: async (fecha, horario) => {
    try {
      return await firestoreDB.verificarDisponibilidad(fecha, horario);
    } catch (error) {
      ErrorHandler.manejarErrorFirestore(error, 'verificar disponibilidad');
      return false; // Por defecto, no disponible si hay error
    }
  },

  generarHorariosDisponibles: async (fecha) => {
    try {
      return await firestoreDB.generarHorariosDisponibles(fecha);
    } catch (error) {
      ErrorHandler.manejarErrorFirestore(error, 'generar horarios');
      return [];
    }
  },

  generarHorariosDisponiblesEspecialista: async (especialistaId, fecha) => {
        try {
            const cacheKey = `${especialistaId}_${fecha}`;
            
            // Verificar si ya tenemos los horarios de este especialista
            const horariosCache = cache.obtener('horarios', cacheKey);
            if (horariosCache) {
                cacheMonitor.incrementHit();
                return horariosCache;
            }
            
            cacheMonitor.incrementMiss();
            
            // OPTIMIZACIÓN: Si ya consultamos este especialista hoy, reutilizar lógica
            const horarios = await firestoreDB.generarHorariosDisponiblesEspecialista(especialistaId, fecha);
            cache.guardar('horarios', horarios, cacheKey);
            return horarios;
        } catch (error) {
            return ErrorHandler.manejarErrorFirestore(error, 'generar horarios de especialista');
        }
    },


  obtenerHorariosComunesDisponibles: async (fecha, gruposEspecialista) => {
    try {
        return await firestoreDB.obtenerHorariosComunesDisponibles(fecha, gruposEspecialista);
    } catch (error) {
        ErrorHandler.manejarErrorFirestore(error, 'obtener horarios comunes');
        return [];
    }
  },

  obtenerTurnosPorFecha: async (fecha) => {
    try {
      return await firestoreDB.obtenerTurnosPorFecha(fecha);
    } catch (error) {
      ErrorHandler.manejarErrorFirestore(error, 'obtener turnos por fecha');
      return [];
    }
  },

  obtenerTurnosSolapados: async (fecha, horario, duracion) => {
    try {
      return await firestoreDB.obtenerTurnosSolapados(fecha, horario, duracion);
    } catch (error) {
      ErrorHandler.manejarErrorFirestore(error, 'obtener turnos solapados');
      return [];
    }
  },

  obtenerConfigGeneral: async () => {
    try {
        return await firestoreDB.obtenerConfigGeneral();
    } catch (error) {
        ErrorHandler.manejarErrorFirestore(error, 'cargar configuración general');
        return {};
    }
  },

  guardarTurno: async (turnoData) => {
    try {
        // La sesión de Google es obligatoria para llegar hasta acá (se exige
        // al avanzar del paso 1 — ver validarPaso). No hay usuarios anónimos.
        if (!usuarioActual) {
            throw new Error('Debés iniciar sesión con Google para reservar un turno.');
        }
        turnoData.userId = usuarioActual.uid;

        return await firestoreDB.guardarTurno(turnoData);
    } catch (error) {
        ErrorHandler.manejarErrorFirestore(error, 'guardar turno');
        throw error;
    }
    },

  bloquearTurnoTemporal: async (fecha, horario, usuarioId) => {
    try {
      return await firestoreDB.bloquearTurnoTemporal(fecha, horario, usuarioId);
    } catch (error) {
      ErrorHandler.manejarErrorFirestore(error, 'bloquear turno temporal');
      return null;
    }
  },

  eliminarBloqueoTemporal: async (bloqueoId) => {
    try {
      return await firestoreDB.eliminarBloqueoTemporal(bloqueoId);
    } catch (error) {
      ErrorHandler.manejarErrorFirestore(error, 'eliminar bloqueo temporal');
      // No hacemos nada, es una operación de limpieza
    }
  }
};

