async function cargarDatosGenerales() {
    try {
        // Siempre se pide fresco (no solo si está vacío) — si no, cambios
        // hechos en el panel admin después de cargar la página (dirección,
        // ubicación, etc.) nunca se reflejan en el resumen del paso 5.
        datosGenerales = await firestoreSeguro.obtenerConfigGeneral();
        
        // Si no hay datos, usar valores por defecto
        if (!datosGenerales || Object.keys(datosGenerales).length === 0) {
            document.getElementById('local-direccion').textContent = "Dirección no disponible";
            document.getElementById('local-telefono').textContent = "Teléfono no disponible";
            document.getElementById('local-email').textContent = "Email no disponible";
            document.getElementById('local-atencion').textContent = "Horarios no disponibles";
            return;
        }
        
        // Acceder a los datos dentro de empresa
        const empresa = datosGenerales.empresa || {};
        
        // Actualizar dirección
        const direccionElement = document.getElementById('local-direccion');
        if (direccionElement && empresa.direccion) {
            direccionElement.textContent = empresa.direccion;
        } else if (direccionElement) {
            direccionElement.textContent = "Dirección no disponible";
        }
        
        // Actualizar teléfono
        const telefonoElement = document.getElementById('local-telefono');
        if (telefonoElement && empresa.telefono) {
            telefonoElement.textContent = empresa.telefono;
        } else if (telefonoElement) {
            telefonoElement.textContent = "Teléfono no disponible";
        }
        
        // Actualizar email
        const emailElement = document.getElementById('local-email');
        if (emailElement && empresa.email) {
            emailElement.textContent = empresa.email;
        } else if (emailElement) {
            emailElement.textContent = "Email no disponible";
        }
        
        // Actualizar horarios de atención (NUEVO)
        const atencionElement = document.getElementById('local-atencion');
        if (atencionElement && empresa.horariosAtencion) {
            atencionElement.textContent = empresa.horariosAtencion;
        } else if (atencionElement) {
            atencionElement.textContent = "Horarios no disponibles";
        }
        
        // Actualizar redes sociales (si existen en empresa)
        // Nota: en Firestore el campo se llama "redes", no "redesSociales", y usa
        // "x" (no "twitter"). Antes de este fix los links nunca se actualizaban.
        if (empresa.redes) {
            const instagramLink = document.getElementById('instagram');
            const equisLink = document.getElementById('equis');
            const whatsappLink = document.getElementById('whatsapp');

            if (instagramLink && empresa.redes.instagram && empresa.redes.instagram !== '#') {
                instagramLink.href = empresa.redes.instagram;
            }

            if (equisLink && empresa.redes.x && empresa.redes.x !== '#') {
                equisLink.href = empresa.redes.x;
            }

            if (whatsappLink && empresa.redes.whatsapp && empresa.redes.whatsapp !== '#') {
                whatsappLink.href = empresa.redes.whatsapp;
            }
        }

        // Inicializar mapas después de cargar los datos
        setTimeout(() => {
            inicializarMapasEnDirecciones();
        }, 100);

    } catch (error) {
        console.error("Error cargando datos del local:", error);
        // Establecer valores por defecto en caso de error
        document.getElementById('local-direccion').textContent = "Dirección no disponible";
        document.getElementById('local-telefono').textContent = "Teléfono no disponible";
        document.getElementById('local-email').textContent = "Email no disponible";
        const atencionElement = document.getElementById('local-atencion');
        if (atencionElement) {
            atencionElement.textContent = "Horarios no disponibles";
        }
    }
}

function escucharCambiosConfigGeneral() {
    db.collection('negocios').doc(obtenerNegocioIdActual())
        .onSnapshot((doc) => {
            if (doc.exists) {
                const data = doc.data();
                // Misma forma anidada que ya espera cargarDatosGenerales()
                // (datosGenerales.empresa.*, datosGenerales.reserva.*).
                datosGenerales = {
                    empresa: {
                        nombre: data.nombre,
                        direccion: data.direccion,
                        telefono: data.telefono,
                        email: data.email,
                        coordenadas: data.coordenadas,
                        horariosAtencion: data.horariosAtencion,
                        redes: data.redes,
                        logoUrl: data.logoUrl
                    },
                    reserva: {
                        señaMinima: data.señaMinima,
                        tipoSenia: data.tipoSenia,
                        maxDiasReserva: data.maxDiasReserva,
                        anticipacionMinima: data.anticipacionMinima
                    }
                };
                cargarDatosGenerales();
            }
        }, (error) => {
            console.error("Error escuchando cambios:", error);
        });
}

