async function avanzarPaso() {
    if (pasoActual >= totalPasos) return;
  
    try {
        toggleLoader(true);

        // Si estamos avanzando al paso 3, verificar si hay selecciones automáticas
        if (pasoActual === 2) {
            const tieneAutomaticos = datosReserva.especialistas.some(esp => esp.id === 'auto');
            
            if (tieneAutomaticos) {
                const success = await buscarEspecialistasAutomaticos();
                if (!success) {
                    toggleLoader(false);
                    return;
                }
            }
        }
        
        const pasoValido = await validarPaso(pasoActual);

        if (!pasoValido) {
            toggleLoader(false);
            return;
        }

        if (pasoActual === 1 && categoriasDeServiciosAutoAsignadas()) {
            // Todas las categorías de los servicios elegidos ya tienen
            // especialista asignado (auto-asignado por ser el único de su
            // categoría) — no hay nada para elegir en el paso 2, se salta
            // directo a fecha y hora.
            pasoActual = 3;
        } else {
            pasoActual++;
        }

        // Se relee antes de mostrar el resumen — si el cliente canceló un
        // turno y generó crédito nuevo en esta misma sesión, sin esto el
        // aviso seguiría mostrando el valor (o la ausencia de crédito) de
        // cuando inició sesión.
        if (usuarioActual) {
            await refrescarCreditoDisponible(usuarioActual.uid);
        }

        actualizarInterfaz();
        actualizarResumenContinuo(pasoActual);

        setTimeout(() => {
            scrollAlInicio();
        }, 100); // Pequeño delay para asegurar que la UI se haya actualizado
        
        // Acciones específicas por paso
        if (pasoActual === 4 && usuarioActual) {
            autocompletarFormulario(usuarioActual);
        }
        
        if (pasoActual === 5) {
            try {
                guardarDatosFormulario();
                actualizarResumen();
                cargarDatosGenerales();
            } catch (error) {
                console.error('Error actualizando resumen:', error);
                mostrarError('Error al generar el resumen. Por favor, recarga la página.');
                // Retroceder al paso anterior si hay error
                pasoActual--;
                actualizarInterfaz();
            }
        }
        
        if (pasoActual === 6) {
            // Aquí va la lógica de confirmación
        }
    } catch (error) {
        console.error('Error al avanzar paso:', error);
        mostrarError('Ocurrió un error al procesar la solicitud');
    } finally {
        toggleLoader(false);
    }
}

function retrocederPaso() {
    if (pasoActual > 1) {
        // Si estamos en fecha/horario y el paso 2 (especialistas) no tiene
        // nada para elegir (todas las categorías se auto-asignaron por tener
        // un solo especialista), no tiene sentido pasar por él al retroceder
        // — se salta directo a servicios.
        if (pasoActual === 3 && categoriasDeServiciosAutoAsignadas()) {
            limpiarSeleccion('horario');
            datosReserva.horario = null;
            pasoActual = 1;
            actualizarInterfaz();
            actualizarResumenContinuo(pasoActual);
            setTimeout(() => {
                scrollAlInicio();
            }, 100);
            return;
        }

        switch (pasoActual) {
            case 2: // Si retrocedemos a servicios
                // Limpiar especialistas y forzar recarga
                datosReserva.especialistas = [];
                // Limpiar selecciones visuales
                document.querySelectorAll('.flotante.especialista.seleccionado').forEach(el => {
                    el.classList.remove('seleccionado');
                });
                document.querySelectorAll('.seleccion-predeterminada.seleccionado').forEach(el => {
                    el.classList.remove('seleccionado');
                    // Restaurar texto predeterminado
                    const infoEspecialista = el.querySelector('.info-especialista');
                    if (infoEspecialista) {
                        infoEspecialista.innerHTML = '<span class="texto-predeterminado">Selecciona un especialista</span>';
                    }
                });
                break;
                
            case 3: // Si retrocedemos a fechas desde horarios
                limpiarSeleccion('horario');
                datosReserva.horario = null;
                break;
                
            case 4: // Si retrocedemos a datos desde resumen
                break;
        }
        
        pasoActual--;
        actualizarInterfaz();
        actualizarResumenContinuo(pasoActual);

        setTimeout(() => {
            scrollAlInicio();
        }, 100);
        
        // FORZAR RECARGA si volvemos al paso 2 (especialistas)
        if (pasoActual === 2) {
            // Recargar especialistas basado en servicios actuales
            const categoriasIds = [...new Set(datosReserva.servicios.map(s => s.categoriaId))];
            mostrarEspecialistas(categoriasIds);
        }
    }
}

async function validarPaso(paso) {
    const pasoElement = document.querySelector(`.paso-${paso}`);
    if (!pasoElement) {
        console.error(`Elemento del paso ${paso} no encontrado`);
        return false;
    }

    // Ocultar todos los mensajes de error primero
    const errores = pasoElement.querySelectorAll('.error-mensaje');
    if (errores) {
        errores.forEach(msg => msg.classList.remove('visible'));
    }

    switch (paso) {
        case 1:
        const errorServicio = pasoElement.querySelector('#error-servicio');
        if (datosReserva.servicios.length === 0) {
            if (errorServicio) {
                errorServicio.classList.add('visible');
                errorServicio.style.animation = 'shake 0.5s';
                setTimeout(() => errorServicio.style.animation = '', 500);
            }
            return false;
        }

        // La reserva ya no admite usuarios anónimos — hace falta una
        // sesión de Google real antes de seguir, para poder identificar
        // al cliente de forma confiable en toda la plataforma.
        const loginRequerido = pasoElement.querySelector('#login-requerido');
        if (!usuarioActual || usuarioActual.isAnonymous) {
            if (loginRequerido) {
                loginRequerido.classList.add('visible');
            }
            return false;
        }
        return true;
            
        case 2: // Validación especialistas
            const errorEspecialista = document.getElementById('error-especialista');
            
            // Verificar que tenemos un especialista para cada categoría de servicios seleccionados
            const categoriasServicios = [...new Set(datosReserva.servicios.map(s => s.categoriaId))];
            const categoriasConEspecialista = [...new Set(datosReserva.especialistas.map(e => e.categoriaId))];
            
            const todasCategoriasCubiertas = categoriasServicios.every(categoriaId => 
                categoriasConEspecialista.includes(categoriaId)
            );
            
            if (!todasCategoriasCubiertas) {
                if (errorEspecialista) {
                    errorEspecialista.textContent = '¡Selecciona un especialista para cada categoría de servicios!';
                    errorEspecialista.classList.add('visible');
                }
                return false;
            }
            return true;
            
        case 3: // Fechas y Horarios
            const errorFecha = document.getElementById('error-fecha');
            const errorHorario = document.getElementById('error-horario');
            
            // DEBUG: Verificar los valores actuales
            
            if (!datosReserva.fecha) {
                if (errorFecha) errorFecha.classList.add('visible');
                return false;
            }
            
            if (!datosReserva.horario) {
                if (errorHorario) errorHorario.classList.add('visible');
                return false;
            }
            
            // Validar disponibilidad en tiempo real
            toggleLoader(true);
            try {
                const duracionTotal = calcularDuracionTotal();
                const validacion = await validarDisponibilidadCompleta(
                    datosReserva.fecha, 
                    datosReserva.horario,
                    duracionTotal
                );
                
                if (!validacion.disponible || validacion.turnosSolapados.length > 0) {
                    mostrarError(validacion.mensaje || 'El horario ya no está disponible para la duración requerida');
                    return false;
                }
                return true;
            } finally {
                toggleLoader(false);
            }
            
        case 4:
            // Validación de campos del formulario
            const formularioValido = validarFormulario();
            
            if (!formularioValido) {
                // Mostrar mensaje general de error
                const errorGeneral = document.createElement('div');
                errorGeneral.className = 'error-general visible';
                errorGeneral.innerHTML = `
                    <svg viewBox="0 0 24 24" width="20" height="20">
                        <path fill="#ff6b6b" d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z"/>
                    </svg>
                    <span>Completa todos los campos correctamente para continuar</span>
                `;
                
                return false;
            }
            
            // Si el formulario es válido, quitar cualquier error general
            const errorGeneralExistente = document.querySelector('.error-general');
            if (errorGeneralExistente) {
                errorGeneralExistente.remove();
            }
            
            return true;
            
        case 5:
            return validarFormulario();
            
        default:
            return true;
    }
}

// A diferencia de una elección manual, cuando una categoría tiene un solo
// especialista activo no hay nada para elegir — mostrarEspecialistas() lo
// marca con autoAsignado:true al asignarlo. Esta función distingue ese caso
// (paso 2 realmente no tiene nada que mostrar) de una categoría con varios
// especialistas donde el usuario ya eligió uno (ahí el paso 2 sigue siendo
// válido para poder cambiar de especialista).
function categoriasDeServiciosAutoAsignadas() {
    const categoriasServicios = [...new Set(datosReserva.servicios.map(s => s.categoriaId))];
    return categoriasServicios.every(categoriaId => {
        const especialista = datosReserva.especialistas.find(e => e.categoriaId === categoriaId);
        return especialista && especialista.autoAsignado === true;
    });
}

function actualizarInterfaz() {
    actualizarPasos();
    actualizarBotones();
    actualizarResumenContinuo(pasoActual);
}

function actualizarPasos() {
    elementos.pasos.forEach((paso, index) => {
        paso.classList.toggle('activo', index + 1 === pasoActual);
    });
}

function actualizarBotones() {
    // Ocultar spinner al cambiar de paso
    const loader = document.getElementById('reserva-loader');
    if (loader) loader.style.display = 'none';

    // Botón anterior
    if (pasoActual === 1) {
        elementos.btnAnterior.classList.remove('activo');
    } else {
        elementos.btnAnterior.classList.add('activo');
    }
    
    // Limpiar eventos previos del botón siguiente
    elementos.btnSiguiente.replaceWith(elementos.btnSiguiente.cloneNode(true));
    elementos.btnSiguiente = document.querySelector('.btn-siguiente');
    
    // Configurar botón siguiente según el paso actual
    if (pasoActual === totalPasos) {
        elementos.btnSiguiente.classList.add('btn-reserva');
        elementos.btnSiguiente.innerHTML = `
            <span class="circulo" aria-hidden="true">
                <span class="icono-flecha flecha"></span>
            </span>
            <span class="texto-reserva">Reservar</span>
        `;
        elementos.btnSiguiente.addEventListener('click', async () => {
            await simularReserva();
        });
    } else {
        elementos.btnSiguiente.classList.remove('btn-reserva');
        elementos.btnSiguiente.innerHTML = `
            <svg class="flecha" viewBox="0 0 24 24" width="24" height="24">
                <path d="M8.59 16.59L13.17 12 8.59 7.41 10 6l6 6-6 6-1.41-1.41z" fill="ffffff"/>
            </svg>
        `;
        elementos.btnSiguiente.addEventListener('click', avanzarPaso);
    }
}

// Función para actualizar el resumen continuo
function actualizarResumenContinuo(paso) {
  const resumenContinuo = document.querySelector('.resumen-continuo');
  const resumenEspecialistas = document.querySelector('.resumen-especialistas');
  const resumenFechaHora = document.querySelector('.resumen-fecha-hora');
  const resumenCliente = document.querySelector('.resumen-cliente');
  // const resumenActions = document.querySelector('.resumen-actions');

  // Mostrar/ocultar según el paso
  if (paso >= 2) {
    resumenContinuo.style.display = 'block';
    actualizarResumenServicios();
    
    if (paso >= 3) {
      if (resumenEspecialistas) {
        resumenEspecialistas.style.display = 'block';
      }
      actualizarResumenEspecialistas();
      
      if (paso >= 4) {
        resumenFechaHora.style.display = 'block';
        actualizarResumenFechaHora();
        
        if (paso >= 5) {
          resumenCliente.style.display = 'block';
          // resumenActions.style.display = 'block';
          actualizarResumenCliente();
        } else {
          resumenCliente.style.display = 'none';
          // resumenActions.style.display = 'none';
        }
      } else {
        resumenFechaHora.style.display = 'none';
        resumenCliente.style.display = 'none';
        // resumenActions.style.display = 'none';
      }
    } else {
      resumenEspecialistas.style.display = 'none';
      resumenFechaHora.style.display = 'none';
      resumenCliente.style.display = 'none';
      // resumenActions.style.display = 'none';
    }
  } else {
    resumenContinuo.style.display = 'none';
  }
}

// Función para hacer scroll al inicio del contenedor de pasos
function scrollAlInicio() {
    const contenedorMaqueta = document.querySelector('.contenedor-maqueta');
    if (contenedorMaqueta) {
        // Scroll suave al inicio del contenedor
        contenedorMaqueta.scrollTo({
            top: 0,
            behavior: 'smooth'
        });
    }
}

function limpiarSeleccion(tipo) {
    document.querySelectorAll(`.flotante.${tipo}.seleccionado`).forEach(elemento => {
        elemento.classList.remove('seleccionado');
    });
    
    const errorElement = document.getElementById(`error-${tipo}`);
    if (errorElement) {
        errorElement.classList.remove('visible');
    }
}

function seleccionarElemento(elemento, tipo) {
    // Si ya está seleccionado y es servicio, deseleccionar
    if (elemento.classList.contains('seleccionado') && tipo === 'servicio') {
        elemento.classList.remove('seleccionado');
        actualizarServiciosSeleccionados();
        return;
    }

    // Para servicios (selección múltiple)
    if (tipo === 'servicio') {
        elemento.classList.add('seleccionado');
        actualizarServiciosSeleccionados();
    } 
    // Para fechas/horarios (selección única)
    else {
        document.querySelectorAll(`.flotante.${tipo}`).forEach(el => {
            el.classList.remove('seleccionado');
        });
        elemento.classList.add('seleccionado');
        datosReserva[tipo] = elemento.querySelector('.p1').textContent;
        
        // Remover mensaje de error si se selecciona
        if (tipo === 'fecha') {
            document.getElementById('error-fecha').classList.remove('visible');
        } else if (tipo === 'horario') {
            document.getElementById('error-horario').classList.remove('visible');
        }
    }
}

