function actualizarServiciosSeleccionados() {
    try {
        
        const serviciosSeleccionados = document.querySelectorAll('.flotante.servicio.seleccionado');
        
        if (!datosReserva.servicios || !Array.isArray(datosReserva.servicios)) {
            datosReserva.servicios = [];
        }
        
        
        if (!serviciosSeleccionados || serviciosSeleccionados.length === 0) {
            datosReserva.servicios = [];
            
            const contenedorEspecialistas = document.querySelector('.contenedor-especialistas');
            if (contenedorEspecialistas) {
                contenedorEspecialistas.innerHTML = '<p class="sin-especialistas">Selecciona servicios primero</p>';
            }
            
            actualizarContadoresCategoria();
            calcularSubtotal();
            return;
        }
        
        const serviciosProcesados = Array.from(serviciosSeleccionados).map(serv => {
            try {
                const servicioId = serv.getAttribute('data-servicio-id');
                const servicioNombre = serv.getAttribute('data-servicio');
                const categoriaId = serv.getAttribute('data-categoria-id');
                
                if (!servicioId || !categoriaId) {
                    console.warn("Servicio sin ID o categoría ID:", serv);
                    return null;
                }
                
                const servicioCompleto = datosReserva.serviciosDisponibles?.find(s => s && s.id === servicioId);
                
                // CALCULAR PRECIO CON DESCUENTO SI APLICA
                const precioOriginal = servicioCompleto ? servicioCompleto.precio : (datosReserva.precios[servicioNombre] || 0);
                const tienePromo = servicioCompleto ? servicioCompleto.promo : false;
                const descuentoPorcentaje = (servicioCompleto && servicioCompleto.descuentoPorcentaje) || 25;
                const precioFinal = tienePromo ? Math.round(precioOriginal * (1 - descuentoPorcentaje / 100)) : precioOriginal;

                return {
                    id: servicioId,
                    nombre: servicioNombre || (servicioCompleto ? servicioCompleto.nombre : 'Servicio'),
                    precio: precioFinal, // Guardamos el precio con descuento aplicado
                    precioOriginal: precioOriginal, // Guardamos el precio original para referencia
                    promo: tienePromo, // Guardamos si tiene promoción
                    descuentoPorcentaje: descuentoPorcentaje,
                    duracion: servicioCompleto ? servicioCompleto.duracion : (datosReserva.duraciones[servicioNombre] || 30),
                    categoriaId: categoriaId
                };
            } catch (error) {
                console.error('Error procesando servicio:', error);
                return null;
            }
        }).filter(servicio => servicio !== null);

        datosReserva.servicios = serviciosProcesados;

        if (!Array.isArray(datosReserva.servicios)) {
            console.error('datosReserva.servicios no es un array, forzando a array vacío');
            datosReserva.servicios = [];
        }

        datosReserva.reserva = calcularSenia();

        actualizarContadoresCategoria();
        
        if (datosReserva.servicios.length > 0) {
            document.getElementById('error-servicio').classList.remove('visible');
        }
        
        
        if (datosReserva.servicios.length > 0) {
            const categoriasIds = [...new Set(datosReserva.servicios.map(s => s.categoriaId))];
            mostrarEspecialistas(categoriasIds);
        } else {
            const contenedorEspecialistas = document.querySelector('.contenedor-especialistas');
            if (contenedorEspecialistas) {
                contenedorEspecialistas.innerHTML = '<p class="sin-especialistas">Selecciona servicios primero</p>';
            }
        }
        
        calcularSubtotal();

        if (pasoActual >= 2) {
            actualizarResumenServicios();
        }
    } catch (error) {
        console.error("Error en actualizarServiciosSeleccionados:", error);
    }
}

function actualizarContadoresCategoria() {
  // Ocultar todos los contadores primero
  document.querySelectorAll('.contador-seleccionados-categoria').forEach(contador => {
    contador.textContent = '';
    contador.classList.remove('mostrar');
  });
  
  // Contar servicios por categoría
  const serviciosPorCategoria = {};
  
  datosReserva.servicios.forEach(servicio => {
    if (servicio.categoriaId) {
      if (!serviciosPorCategoria[servicio.categoriaId]) {
        serviciosPorCategoria[servicio.categoriaId] = 0;
      }
      serviciosPorCategoria[servicio.categoriaId]++;
    }
  });
  
  // Actualizar contadores
  Object.keys(serviciosPorCategoria).forEach(categoriaId => {
    const contador = document.querySelector(
      `.categoria-header[data-categoria-id="${categoriaId}"] .contador-seleccionados-categoria`
    );
    
    if (contador && serviciosPorCategoria[categoriaId] > 0) {
      contador.textContent = serviciosPorCategoria[categoriaId];
      // Pequeño retraso para permitir que el DOM se actualice antes de la animación
      setTimeout(() => {
        contador.classList.add('mostrar');
      }, 10);
    }
  });
}

function calcularSubtotal() {
    const subtotal = datosReserva.servicios.reduce((total, servicio) => total + servicio.precio, 0);
    
    // Calcular ahorro total por promociones
    const ahorroTotal = datosReserva.servicios.reduce((total, servicio) => {
        return servicio.promo ? total + (servicio.precioOriginal - servicio.precio) : total;
    }, 0);
    
    // Mostrar ahorro si hay promociones
    if (ahorroTotal > 0) {
        // Puedes mostrar esto en la UI si quieres
        const elementoAhorro = document.getElementById('ahorro-total');
        if (elementoAhorro) {
            elementoAhorro.textContent = `-$${ahorroTotal.toLocaleString()}`;
            elementoAhorro.style.display = 'block';
        }
    }
    
    return subtotal;
}

function calcularDuracionTotal() {
    return datosReserva.servicios.reduce((total, servicio) => total + servicio.duracion, 0);
}

// Función para calcular la seña. Dos modos configurables por negocio:
// - "porTiempo" (default): señaMinima por cada 30 minutos de duración total.
// - "porcentual": 10% del valor total del turno.
// En ambos casos nunca se cobra menos que señaMinima.
function calcularSenia() {
    const señaMinima = datosGenerales?.reserva?.señaMinima || 1000;
    const tipoSenia = datosGenerales?.reserva?.tipoSenia || 'porTiempo';

    if (tipoSenia === 'porcentual') {
        const subtotal = calcularSubtotal();
        return Math.max(Math.round(subtotal * 0.10), señaMinima);
    }

    const duracionTotal = calcularDuracionTotal();
    const multiplicador = Math.ceil(duracionTotal / 30);
    return multiplicador * señaMinima;
}


