function seleccionarEspecialista(elemento, especialista, categoriaId) {
    // Validar parámetros
    if (!especialista || !categoriaId) {
        console.error('Parámetros inválidos en seleccionarEspecialista:', { elemento, especialista, categoriaId });
        return;
    }
    
    // Obtener el contenedor de la categoría
    const categoriaSection = document.querySelector(`.categoria-especialistas[data-categoria-id="${categoriaId}"]`);
    if (!categoriaSection) return;
    
    const seleccionPredeterminada = categoriaSection.querySelector('.seleccion-predeterminada');
    const especialistasContainer = categoriaSection.querySelector('.especialistas-lista');
    const infoEspecialista = seleccionPredeterminada.querySelector('.info-especialista');
    
    // Verificar si ya está seleccionado para esta categoría
    const especialistaExistenteIndex = datosReserva.especialistas.findIndex(
        e => e.categoriaId === categoriaId
    );
    
    // Si ya hay un especialista para esta categoría, eliminarlo
    if (especialistaExistenteIndex !== -1) {
        datosReserva.especialistas.splice(especialistaExistenteIndex, 1);
    }
    
    // ✅ MEJORAR: Obtener la foto del especialista
    let fotoUrl = 'img/avatar-default.png';
    if (especialista.fotoUrl) {
        fotoUrl = especialista.fotoUrl;
    } else if (elemento) {
        const img = elemento.querySelector('.avatar-especialista');
        if (img) fotoUrl = img.src;
    }
    
    // Guardar datos
    datosReserva.especialistas.push({
        id: especialista.id,
        nombre: especialista.nombre,
        categoriaId: categoriaId,
        fotoUrl: fotoUrl // ✅ GUARDAR LA FOTO CONSISTENTEMENTE
    });
    
    // Remover error si existe
    const errorEspecialista = document.getElementById('error-especialista');
    if (errorEspecialista) errorEspecialista.classList.remove('visible');
    
    // Actualizar la UI
    
    // 1. Deseleccionar todos los especialistas en esta categoría
    especialistasContainer.querySelectorAll('.flotante.especialista').forEach(el => {
        el.classList.remove('seleccionado');
    });
    
    // 2. Seleccionar el elemento clickeado
    if (elemento) {
        elemento.classList.add('seleccionado');
    }
    
    // 3. Actualizar la selección predeterminada
    seleccionPredeterminada.classList.add('seleccionado');
    
    // Actualizar solo el contenido de info-especialista, no todo el HTML
    if (especialista.id === 'auto') {
        infoEspecialista.innerHTML = `
            <span class="texto-predeterminado">Con quien tenga disponibilidad</span>
        `;
    } else {
        // Buscar el especialista en la lista para obtener más datos (como la foto)
        const especialistaCompleto = Array.from(especialistasContainer.querySelectorAll('.flotante.especialista'))
            .find(el => el.dataset.id === especialista.id);
        
        let avatarUrl = 'img/avatar-default.png';
        if (especialistaCompleto) {
            const img = especialistaCompleto.querySelector('.avatar-especialista');
            if (img) avatarUrl = img.src;
        }
        
        infoEspecialista.innerHTML = `
            <img src="${avatarUrl}" alt="${especialista.nombre}" class="avatar-especialista">
            <div>
                <span class="nombre-especialista">${especialista.nombre}</span>
            </div>
        `;
    }
    
    // El botón con el SVG ya existe, no necesitamos recrearlo
    // Solo necesitamos asegurarnos de que el evento esté configurado
    
    // Configurar el evento del botón si no está configurado
    const btnVerEspecialistas = seleccionPredeterminada.querySelector('.btn-ver-especialistas');
    if (btnVerEspecialistas && !btnVerEspecialistas.hasEventListener) {
        btnVerEspecialistas.addEventListener('click', (e) => {
            e.stopPropagation();
            const lista = categoriaSection.querySelector('.especialistas-lista');
            const icono = btnVerEspecialistas.querySelector('.acordeon-icon');
            toggleListaEspecialistas(lista, icono);
        });
        
        // Marcar que este botón ya tiene el event listener
        btnVerEspecialistas.hasEventListener = true;
    }
    
    if (pasoActual >= 2) {
        actualizarResumenEspecialistas();
    }

    // FORZAR RECARGA de fechas cuando cambia la selección
    limpiarFechasYHorarios();
    
}


async function cargarEspecialistas() {
    try {
        // Obtener categorías únicas de los servicios seleccionados
        const categoriasIds = [...new Set(datosReserva.servicios.map(s => s.categoriaId))];
        
        if (categoriasIds.length === 0) {
            console.warn("No hay categorías para cargar especialistas");
            return;
        }
        
        // Obtener especialistas para cada categoría
        const especialistasPromises = categoriasIds.map(catId => 
            firestoreSeguro.obtenerEspecialistasPorCategoria(catId)
        );
        
        const resultados = await Promise.allSettled(especialistasPromises);
        
        // Procesar resultados
        const especialistasPorCategoria = {};
        resultados.forEach((result, index) => {
            if (result.status === 'fulfilled') {
                especialistasPorCategoria[categoriasIds[index]] = result.value;
            } else {
                console.error(`Error cargando especialistas para categoría ${categoriasIds[index]}:`, result.reason);
                especialistasPorCategoria[categoriasIds[index]] = [];
            }
        });
        
        // Mostrar especialistas en la UI
        mostrarEspecialistas(categoriasIds, especialistasPorCategoria);
        
    } catch (error) {
        console.error("Error cargando especialistas:", error);
        mostrarError("Error al cargar los especialistas. Intenta nuevamente.");
    }
}

async function buscarEspecialistasAutomaticos() {
    try {
        const especialistasAutomaticos = datosReserva.especialistas.filter(esp => esp.id === 'auto');
        
        for (const espAuto of especialistasAutomaticos) {
            const mejorEspecialista = await obtenerEspecialistaConMejorDisponibilidad(espAuto.categoriaId);
            
            if (mejorEspecialista) {
                // Reemplazar la selección automática con el especialista real
                const index = datosReserva.especialistas.findIndex(esp => 
                    esp.id === 'auto' && esp.categoriaId === espAuto.categoriaId
                );
                
                if (index !== -1) {
                    datosReserva.especialistas[index] = {
                        id: mejorEspecialista.id,
                        nombre: mejorEspecialista.nombre,
                        categoriaId: espAuto.categoriaId,
                        fotoUrl: mejorEspecialista.fotoUrl || 'img/avatar-default.png' // ✅ AGREGAR LA FOTO
                    };
                    
                }
            } else {
                throw new Error(`No se encontró especialista disponible para la categoría ${espAuto.categoriaId}`);
            }
        }
        
        return true;
    } catch (error) {
        console.error("Error buscando especialistas automáticos:", error);
        mostrarError("No se pudo encontrar especialistas disponibles. Por favor, selecciona manualmente.");
        return false;
    }
}

