// Función para cargar horarios para una fecha específica
async function cargarHorariosParaFecha(fecha) {
    try {
        // Mostrar loader
        const cargandoHorarios = document.querySelector('.cargando-horarios');
        const contenedorHorarios = document.querySelector('.contenedor-horarios');
        const sinHorarios = document.querySelector('.sin-horarios');
        
        if (cargandoHorarios) cargandoHorarios.style.display = 'block';
        if (contenedorHorarios) contenedorHorarios.innerHTML = '';
        if (sinHorarios) sinHorarios.style.display = 'none';
        
        const duracionTotal = calcularDuracionTotal();
        const gruposEspecialista = agruparServiciosPorEspecialista();


        // Obtener horarios disponibles: cada especialista involucrado libre
        // para el sub-bloque que le corresponde (secuencial, no en paralelo)
        let horariosDisponibles = await firestoreDB.obtenerHorariosComunesDisponibles(
            fecha,
            gruposEspecialista
        );

        // Sacar los horarios que chocarían con otro turno que el propio
        // cliente ya tenga ese día — no tiene sentido ni dejarlo elegir.
        horariosDisponibles = await filtrarHorariosSinConflictoPropio(fecha, horariosDisponibles, duracionTotal);


        // Si es hoy, filtrar horarios que ya pasaron
        const hoy = formatearFechaLocal(obtenerAhoraArgentina());
        let horariosFiltrados = horariosDisponibles;

        if (fecha === hoy) {
            // CORRECCIÓN: Solo filtrar por hora actual, la duración ya se consideró en Firestore
            horariosFiltrados = filtrarHorariosPorHoraActual(horariosDisponibles, duracionTotal);
        }

        // Ocultar loader
        if (cargandoHorarios) cargandoHorarios.style.display = 'none';
        
        // Actualizar UI
        actualizarUIHorarios(horariosFiltrados);
        
    } catch (error) {
        console.error("Error cargando horarios:", error);
        mostrarError("No se pudieron cargar los horarios disponibles");
        
        // Ocultar loader en caso de error
        const cargandoHorarios = document.querySelector('.cargando-horarios');
        if (cargandoHorarios) cargandoHorarios.style.display = 'none';
    }
}

// Función para filtrar horarios por hora actual
function filtrarHorariosPorHoraActual(horarios, duracionTotal) {
    const ahora = new Date();
    const horaActual = ahora.getHours();
    const minutoActual = ahora.getMinutes();
    const tiempoActualMinutos = horaActual * 60 + minutoActual;
    const anticipacionMinima = datosGenerales?.reserva?.anticipacionMinima ?? 30;


    const horariosFiltrados = horarios.filter(horario => {
        const [horaStr, minutoStr] = horario.split(':');
        const horaHorario = parseInt(horaStr);
        const minutoHorario = parseInt(minutoStr);
        const tiempoHorarioMinutos = horaHorario * 60 + minutoHorario;

        // Buffer de anticipación mínima configurado por el negocio
        return tiempoHorarioMinutos >= (tiempoActualMinutos + anticipacionMinima);
    });

    return horariosFiltrados;
}

