// Función para renderizar el calendario
function renderizarCalendario() {
    const mesAnioElement = document.querySelector('.calendario-mes');
    const diasContainer = document.querySelector('.calendario-dias');
    
    if (!mesAnioElement || !diasContainer) {
        console.error("Elementos del calendario no encontrados");
        return;
    }
    
    // Obtener mes y año
    const mes = calendarioFechaActual.getMonth();
    const anio = calendarioFechaActual.getFullYear();
    
    // Nombres de los meses
    const nombresMeses = [
        'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
        'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'
    ];
    
    // Actualizar el encabezado
    mesAnioElement.innerHTML = `${nombresMeses[mes]} <span>${anio}</span>`;
    
    // Obtener el primer día del mes y la cantidad de días
    const primerDia = new Date(anio, mes, 1);
    const ultimoDia = new Date(anio, mes + 1, 0);
    const diasEnMes = ultimoDia.getDate();
    
    // Obtener el día de la semana del primer día (0 = Domingo, 1 = Lunes, etc.)
    const diaInicio = primerDia.getDay();
    
    // Limpiar el contenedor de días
    diasContainer.innerHTML = '';
    
    // Agregar días vacíos para alinear el primer día
    for (let i = 0; i < diaInicio; i++) {
        const diaVacio = document.createElement('div');
        diaVacio.className = 'dia-calendario fuera-de-mes';
        diasContainer.appendChild(diaVacio);
    }
    
    // Obtener la fecha actual para resaltar el día de hoy
    const hoyFormateado = formatearFechaLocal(obtenerAhoraArgentina());

    
    // Agregar los días del mes
    for (let dia = 1; dia <= diasEnMes; dia++) {
        const diaElement = document.createElement('div');
        diaElement.className = 'dia-calendario';
        diaElement.textContent = dia;
        
        // La fecha ya está en formato YYYY-MM-DD, no hace falta pasarla por
        // Date ni por toISOString() (eso solo arriesga desfasarla de día).
        const fechaFormateada = `${anio}-${String(mes + 1).padStart(2, '0')}-${String(dia).padStart(2, '0')}`;
        const fechaLocal = fechaFormateada;
        
        // Agregar data-atributo con la fecha
        diaElement.dataset.fecha = fechaLocal;
        
        // Verificar si es hoy
        const hoyFormateado = formatearFechaLocal(obtenerAhoraArgentina());

        if (fechaLocal === hoyFormateado) {
            diaElement.classList.add('hoy');
        }
        
        // Verificar si la fecha está disponible
        const disponible = fechasDisponiblesCalendario.some(f => f.fecha === fechaLocal);
        
        if (disponible) {
            diaElement.classList.add('disponible');
            diaElement.addEventListener('click', () => seleccionarFechaCalendario(fechaLocal, diaElement));
        } else {
            diaElement.classList.add('no-disponible');
        }
        
        diasContainer.appendChild(diaElement);
    }
}


