async function validarDisponibilidadCompleta(fecha, horario, duracion) {
    try {
        // Agregar validación para horario
        if (!horario) {
            return {
                disponible: false,
                turnosSolapados: [],
                slotsOcupados: [],
                mensaje: "Horario no seleccionado"
            };
        }

        const config = await firestoreSeguro.obtenerConfiguracion();
        
        // Obtener IDs de especialistas seleccionados
        const especialistasIds = datosReserva.especialistas.map(esp => esp.id);
        
        // Convertir horario de inicio a minutos
        const [horaStr, minutoStr] = horario.split(':');
        const horaInicio = parseInt(horaStr);
        const minutoInicio = parseInt(minutoStr);
        const inicioMinutos = horaInicio * 60 + minutoInicio;
        const finMinutos = inicioMinutos + duracion;
        
        // Obtener todos los turnos del día para los especialistas seleccionados
        const turnosDelDia = await firestoreDB.obtenerTurnosPorEspecialistasYFecha(especialistasIds, fecha);
        
        // Verificar solapamientos solo para los especialistas seleccionados
        const turnosSolapados = turnosDelDia.filter(turno => {
            const [turnoHora, turnoMinuto] = turno.horarioInicio.split(':').map(Number);
            const turnoInicioMin = turnoHora * 60 + turnoMinuto;
            const turnoFinMin = turnoInicioMin + (turno.duracionTotal || 30);
            
            // Verificar solapamiento
            return !(finMinutos <= turnoInicioMin || inicioMinutos >= turnoFinMin);
        });
        
        // slotsOcupados existía como segundo chequeo, slot por slot, con una
        // consulta a Firestore POR CADA slot de 30' dentro de la duración —
        // redundante con turnosSolapados (mismos datos, ya en memoria) y
        // además más débil: solo detectaba un turno si su horarioInicio
        // coincidía EXACTO con el slot probado, no si lo cubría por estar
        // en el medio de un turno más largo (turnosSolapados sí lo hace,
        // por rango). Se saca el segundo chequeo entero — turnosSolapados ya
        // cubre todo lo que cubría, sin gastar lecturas extra de Firestore.
        const slotsOcupados = [];
        const disponible = turnosSolapados.length === 0;
        
        let mensaje = '';
        if (!disponible) {
            const horas = Math.floor(duracion / 60);
            const minutos = duracion % 60;
            
            mensaje = `Tu turno necesita ${horas > 0 ? horas + ' hora' + (horas > 1 ? 's' : '') + ' y ' : ''}${minutos} minutos continuos.`;
        }
        
        return {
            disponible,
            turnosSolapados,
            slotsOcupados,
            mensaje
        };
    } catch (error) {
        console.error("Error en validación:", error);
        return {
            disponible: false,
            turnosSolapados: [],
            slotsOcupados: [],
            mensaje: "Error al verificar disponibilidad. Por favor, intenta nuevamente."
        };
    }
}

// Función para verificar disponibilidad de un especialista específico.
// `cache`, si viene (ver construirCacheDisponibilidadEspecialistas), evita
// la lectura del documento del especialista y de sus bloqueos.
async function verificarDisponibilidadEspecialista(especialistaId, fecha, cache = null) {
    try {
        let especialistaData;
        let bloqueosPrecargados = null;

        if (cache && cache[especialistaId]) {
            especialistaData = cache[especialistaId].especialistaData;
            bloqueosPrecargados = cache[especialistaId].bloqueos;
            if (!especialistaData) return false;
        } else {
            const especialistaDoc = await db.collection('especialistas').doc(especialistaId).get();
            if (!especialistaDoc.exists) {
                return false;
            }
            especialistaData = especialistaDoc.data();
        }

        // 2. Día de la semana de esta fecha, calculado con componentes
        // locales (ver comentario en obtenerDiaSemanaDeFechaStr, global.js)
        // — el bug original acá era justamente el patrón que esa función
        // existe para evitar.
        const diaSemana = obtenerDiaSemanaDeFechaStr(fecha);

        // Mapeo de días
        const diasMap = {
            0: 'domingo',
            1: 'lunes',
            2: 'martes',
            3: 'miercoles',
            4: 'jueves',
            5: 'viernes',
            6: 'sabado'
        };

        const diaKey = diasMap[diaSemana];


        // Si no trabaja ese día, no está disponible
        if (!especialistaData.horarioLaboral || !especialistaData.horarioLaboral[diaKey]?.activo) {
            return false;
        }

        // Techo obligatorio: los días laborales del NEGOCIO son el límite
        // real, sin importar lo que diga el horario propio del especialista.
        // El formulario de Personal ya impide marcar un día fuera de este
        // rango, pero eso no corrige datos que hayan quedado inconsistentes
        // de antes (p. ej. un especialista con un día activo que el negocio
        // dejó de atender) — este chequeo es la red de seguridad real.
        const config = await firestoreSeguro.obtenerConfiguracion();
        const diasLaborales = Array.isArray(config.diasLaborales) ? config.diasLaborales.map(Number) : [];
        if (!diasLaborales.includes(diaSemana)) {
            return false;
        }

        // 3. Verificar si tiene bloqueos/ausencias para esa fecha
        const tieneBloqueos = bloqueosPrecargados
            ? algunBloqueoIncluyeFecha(bloqueosPrecargados, fecha)
            : await verificarBloqueosEspecialista(especialistaId, fecha);
        if (tieneBloqueos) {
            return false;
        }
        
        return true;
        
    } catch (error) {
        console.error("Error verificando disponibilidad del especialista:", error);
        return false;
    }
}

// `cache`, si se pasa (ver construirCacheDisponibilidadEspecialistas), evita
// volver a leer Firestore por cada especialista — se arma una sola vez para
// todo el rango de fechas que se esté evaluando.
async function verificarDisponibilidadEspecialistas(fecha, cache = null) {
    try {
        if (!datosReserva.especialistas || datosReserva.especialistas.length === 0) {
            return false;
        }

        for (const especialista of datosReserva.especialistas) {
            const disponible = await verificarDisponibilidadEspecialista(especialista.id, fecha, cache);

            if (!disponible) {
                return false;
            }
        }

        return true;

    } catch (error) {
        console.error("Error verificando disponibilidad:", error);
        return false;
    }
}

// Función para verificar disponibilidad de todos los especialistas en una fecha
// Trae, una sola vez por especialista, el documento del especialista y sus
// bloqueos — para reutilizar en un rango de varios días sin repetir la
// misma lectura en cada iteración (ver uso en generarFechasDisponiblesCon-
// Especialistas y obtenerPrimeraFechaDisponibleEspecialistas, que antes
// releían esto por cada día del rango, hasta 14-60 veces por especialista).
async function construirCacheDisponibilidadEspecialistas(especialistaIds) {
    const cache = {};
    await Promise.all(especialistaIds.map(async (especialistaId) => {
        const [especialistaDoc, bloqueosSnapshot] = await Promise.all([
            db.collection('especialistas').doc(especialistaId).get(),
            db.collection('bloqueos')
                .where('negocioId', '==', obtenerNegocioIdActual())
                .where('especialistaId', '==', especialistaId)
                .get()
        ]);
        cache[especialistaId] = {
            especialistaData: especialistaDoc.exists ? especialistaDoc.data() : null,
            bloqueos: bloqueosSnapshot.docs.map(doc => doc.data())
        };
    }));
    return cache;
}

function algunBloqueoIncluyeFecha(bloqueos, fecha) {
    const fechaTimestamp = new Date(fecha).getTime();
    return bloqueos.some(bloqueo => {
        const inicioBloqueo = new Date(bloqueo.fechaInicio).getTime();
        const finBloqueo = new Date(bloqueo.fechaFin).getTime();
        return fechaTimestamp >= inicioBloqueo && fechaTimestamp <= finBloqueo;
    });
}

// Función para verificar bloqueos del especialista (lectura directa, sin
// caché — usar construirCacheDisponibilidadEspecialistas + algunBloqueo-
// IncluyeFecha cuando se va a chequear un rango de varios días).
async function verificarBloqueosEspecialista(especialistaId, fecha) {
    try {
        const snapshot = await db.collection('bloqueos')
            .where('negocioId', '==', obtenerNegocioIdActual())
            .where('especialistaId', '==', especialistaId)
            .get();

        return algunBloqueoIncluyeFecha(snapshot.docs.map(doc => doc.data()), fecha);

    } catch (error) {
        console.error("Error verificando bloqueos:", error);
        return false;
    }
}

// Un mismo cliente no puede tener dos turnos que se solapen en el tiempo,
// aunque sean con especialistas distintos (o incluso en otro negocio de la
// plataforma — la identidad, Google o anónima, es la misma persona
// físicamente, no puede estar en dos lugares a la misma hora). El bloque
// ocupado de un turno es [horarioInicio, horarioInicio + duracionTotal),
// igual que ya se calcula para la disponibilidad por especialista — así un
// turno con varios servicios se compara por su rango completo, no por un
// punto exacto. Devuelve el turno en conflicto, o null si no hay ninguno.
async function verificarConflictoTurnoPropio(fecha, horarioInicio, duracionTotal) {
    if (!usuarioActual) return null;

    const [horaStr, minutoStr] = horarioInicio.split(':').map(Number);
    const inicioMinutos = horaStr * 60 + minutoStr;
    const finMinutos = inicioMinutos + duracionTotal;

    const turnosDelCliente = await firestoreDB.obtenerTurnosPorUsuario(usuarioActual.uid);

    return turnosDelCliente.find(turno => {
        if (turno.fecha !== fecha) return false;

        const [th, tm] = turno.horarioInicio.split(':').map(Number);
        const turnoInicioMin = th * 60 + tm;
        const turnoFinMin = turnoInicioMin + (turno.duracionTotal || 30);

        return !(finMinutos <= turnoInicioMin || inicioMinutos >= turnoFinMin);
    }) || null;
}

// Igual que verificarConflictoTurnoPropio, pero aplicado a toda una lista de
// horarios candidatos — se usa al mostrar el calendario, para que un
// horario que chocaría con otro turno propio directamente no aparezca como
// opción (en vez de dejar elegirlo y recién avisar al confirmar).
async function filtrarHorariosSinConflictoPropio(fecha, horarios, duracionTotal) {
    if (!usuarioActual || horarios.length === 0) return horarios;

    const turnosDelCliente = (await firestoreDB.obtenerTurnosPorUsuario(usuarioActual.uid))
        .filter(turno => turno.fecha === fecha);

    if (turnosDelCliente.length === 0) return horarios;

    return horarios.filter(horario => {
        const [horaStr, minutoStr] = horario.split(':').map(Number);
        const inicioMinutos = horaStr * 60 + minutoStr;
        const finMinutos = inicioMinutos + duracionTotal;

        return !turnosDelCliente.some(turno => {
            const [th, tm] = turno.horarioInicio.split(':').map(Number);
            const turnoInicioMin = th * 60 + tm;
            const turnoFinMin = turnoInicioMin + (turno.duracionTotal || 30);
            return !(finMinutos <= turnoInicioMin || inicioMinutos >= turnoFinMin);
        });
    });
}


// Función para formatear fecha para display
function formatearFechaDisplay(fecha) {
  // Asegurarnos de que tenemos un objeto Date válido
  let fechaObj;
  
  if (typeof fecha === 'string') {
    // Si es una cadena en formato YYYY-MM-DD, convertirla a Date
    fechaObj = parsearFechaLocal(fecha);
  } else if (fecha instanceof Date) {
    fechaObj = fecha;
  } else {
    return "Fecha inválida";
  }
  
  return fechaObj.toLocaleDateString('es-AR', {
    weekday: 'long',
    day: 'numeric',
    month: 'short'
  });
}

// Función para calcular horario de finalización
function calcularHorarioFin(horarioInicio, duracionMinutos) {
    const [horaStr, minutoStr] = horarioInicio.split(':');
    let hora = parseInt(horaStr);
    let minuto = parseInt(minutoStr);
    
    minuto += duracionMinutos;
    hora += Math.floor(minuto / 60);
    minuto = minuto % 60;
    
    return `${hora.toString().padStart(2, '0')}:${minuto.toString().padStart(2, '0')}`;
}


