function validarFormulario() {
    let valido = true;
    
    // Ocultar todos los mensajes de error primero
    document.querySelectorAll('.error-mensaje').forEach(msg => {
        msg.classList.remove('visible');
    });
    
    // Validar cada campo
    const nombreValido = validarNombre();
    const emailValido = validarEmail();
    const telefonoValido = validarTelefono();
    
    // Mostrar errores generales si los campos están vacíos
    if (!document.getElementById('nombre').value.trim()) {
        document.getElementById('error-nombre').textContent = 'El nombre es obligatorio';
        document.getElementById('error-nombre').classList.add('visible');
        document.getElementById('nombre').classList.add('invalido');
        valido = false;
    }
    
    if (!document.getElementById('email').value.trim()) {
        document.getElementById('error-email').textContent = 'El email es obligatorio';
        document.getElementById('error-email').classList.add('visible');
        document.getElementById('email').classList.add('invalido');
        valido = false;
    }
    
    if (!document.getElementById('telefono').value) {
        document.getElementById('error-telefono').textContent = 'El teléfono es obligatorio';
        document.getElementById('error-telefono').classList.add('visible');
        document.getElementById('telefono').classList.add('invalido');
        valido = false;
    }
    
    // Si hay valores pero son inválidos
    if (!nombreValido && document.getElementById('nombre').value.trim()) {
        valido = false;
    }
    
    if (!emailValido && document.getElementById('email').value.trim()) {
        valido = false;
    }
    
    if (!telefonoValido && document.getElementById('telefono').value) {
        valido = false;
    }
    
    return valido;
}

function validarNombre() {
    const input = document.getElementById('nombre');
    const errorMsg = document.getElementById('error-nombre');
    const valor = input.value.trim();
    
    // Validar que tenga al menos 2 palabras con mínimo 2 caracteres cada una
    const palabras = valor.split(' ').filter(word => word.length > 1);
    const valido = palabras.length >= 1 && valor.length >= 5;
    
    if (valido) {
        input.classList.remove('invalido');
        errorMsg.classList.remove('visible');
    } else {
        input.classList.add('invalido');
        if (valor.length > 0) {
            errorMsg.textContent = 'Debe tener al menos 5 caracteres';
            errorMsg.classList.add('visible');
        }
    }
    
    return valido;
}

function validarTelefono() {
    const input = document.getElementById('telefono');
    const errorMsg = document.getElementById('error-telefono');
    const valor = input.value.replace(/\D/g, ''); // Solo números
    const valido = valor.length === 10; // 10 dígitos para Argentina
    
    // Actualizar el valor solo con números
    input.value = valor;
    
    if (valido) {
        input.classList.remove('invalido');
        errorMsg.classList.remove('visible');
    } else {
        input.classList.add('invalido');
        if (valor.length > 0) {
            errorMsg.textContent = 'El teléfono debe tener 10 números';
            errorMsg.classList.add('visible');
        }
    }
    
    return valido;
}

// Nueva función para validar email
function validarEmail() {
    const input = document.getElementById('email');
    const errorMsg = document.getElementById('error-email');
    const valor = input.value.trim();
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const valido = emailRegex.test(valor);
    
    if (valido) {
        input.classList.remove('invalido');
        errorMsg.classList.remove('visible');
    } else {
        input.classList.add('invalido');
        if (valor.length > 0) {
            errorMsg.textContent = 'Ingresa un email válido';
            errorMsg.classList.add('visible');
        }
    }
    
    return valido;
}

function guardarDatosFormulario() {
    datosReserva.nombre = document.getElementById('nombre').value.trim();
    datosReserva.email = document.getElementById('email').value.trim();
    datosReserva.telefono = document.getElementById('telefono').value.trim();
    datosReserva.observacion = document.getElementById('observacion').value.trim() || 'Sin observaciones';
}

async function cargarDatosUsuario(uid) {
    try {
        const userDoc = await db.collection('usuarios').doc(uid).get();
        if (userDoc.exists) {
            const userData = userDoc.data();
            // Prellenar formulario si está disponible
            if (document.getElementById('nombre') && userData.nombre) {
                document.getElementById('nombre').value = userData.nombre;
            }
            if (document.getElementById('telefono') && userData.telefono) {
                document.getElementById('telefono').value = userData.telefono;
            }
        }
    } catch (error) {
        console.error("Error cargando datos usuario:", error);
    }

    await refrescarCreditoDisponible(uid);
    if (pasoActual === 5) {
        actualizarResumenServicios();
    }
}

// Crédito por cancelación en ESTE negocio (single-use, ver cancelarTurno en
// functions/index.js) — se lee directo de Firestore, la lectura ya está
// permitida por las reglas para el propio dueño del crédito. Si el negocio
// nunca activó pagos, o el cliente nunca canceló nada, este documento
// simplemente no existe. Se vuelve a pedir en cada avance de paso (ver
// avanzarPaso) y no solo al iniciar sesión — si no, cancelar un turno y
// generar crédito nuevo en la misma sesión nunca se reflejaba sin recargar
// la página entera.
async function refrescarCreditoDisponible(uid) {
    if (!uid) {
        creditoDisponibleNegocio = 0;
        return;
    }
    try {
        const creditoDoc = await db.collection('negocios').doc(obtenerNegocioIdActual())
            .collection('creditos').doc(uid).get();
        creditoDisponibleNegocio = creditoDoc.exists ? (creditoDoc.data().montoDisponible || 0) : 0;
    } catch (error) {
        console.error('Error cargando crédito disponible:', error);
        creditoDisponibleNegocio = 0;
    }
}

