// Si el cliente tiene crédito de una cancelación anterior en este negocio,
// se lo muestra antes de reservar — se gasta entero de una sola vez (si
// sobra respecto a la seña, se pierde el resto; si no alcanza, se cobra
// la diferencia por Mercado Pago). Ver cancelarTurno/crearPreferenciaPago
// en functions/index.js, que son quienes de verdad aplican el descuento.
function actualizarAvisoCredito(totalSenia) {
  const filaOriginal = document.getElementById('precio-senia-fila');
  const filaConCredito = document.getElementById('resumen-senia-credito');
  const seniaOriginal = document.getElementById('resumen-senia');
  if (!filaOriginal || !filaConCredito || !seniaOriginal) return;

  if (!creditoDisponibleNegocio || creditoDisponibleNegocio <= 0) {
    filaOriginal.classList.remove('tachado');
    filaConCredito.style.display = 'none';
    return;
  }

  const aPagar = Math.max(totalSenia - creditoDisponibleNegocio, 0);
  const seniaFinal = document.getElementById('resumen-senia-final');
  const explicacion = document.getElementById('resumen-credito-explicacion');

  filaOriginal.classList.add('tachado');
  if (seniaFinal) seniaFinal.textContent = aPagar > 0 ? `$${aPagar.toLocaleString()}` : 'Gratis';
  if (explicacion) {
    explicacion.textContent = aPagar > 0
      ? `Tenés $${creditoDisponibleNegocio.toLocaleString()} de crédito disponible (de una cancelación anterior en este negocio) — se descuenta de la seña.`
      : `Tenés $${creditoDisponibleNegocio.toLocaleString()} de crédito disponible (de una cancelación anterior en este negocio) — cubre la seña por completo.`;
  }
  filaConCredito.style.display = 'flex';
}

