// Freno contra doble reserva: un doble click/doble tap en "Reservar" puede
// disparar dos llamadas a simularReserva() antes de que la primera termine
// de guardar en Firestore (ocultar el botón con CSS no alcanza — el click
// ya se procesó del lado del navegador). Con este flag, la segunda llamada
// se corta al toque, sin siquiera tocar Firestore.
let reservaEnProceso = false;

async function simularReserva() {
    if (reservaEnProceso) return;

    if (pasoActual === totalPasos) {
        reservaEnProceso = true;
        const loader = document.getElementById('reserva-loader');
        const btnSiguiente = document.querySelector('.btn-siguiente');
        const errorReserva = document.getElementById('error-reserva');
        const duracionTotal = calcularDuracionTotal();

        // Ocultar cualquier error previo
        if (errorReserva) errorReserva.style.display = 'none';
        
        btnSiguiente.classList.add('hidden');
        // Si algún chequeo posterior falla rápido (antes de los 200ms), hay
        // que cancelar este timeout — si no, el loader queda mostrado de
        // nuevo después de haberlo ocultado, y se ve trabado para siempre.
        const loaderTimeoutId = setTimeout(() => {
        loader.style.display = 'inline-block';
        }, 200);
        
        try {
        // Validación completa
        const validacion = await validarDisponibilidadCompleta(
            datosReserva.fecha, 
            datosReserva.horario,
            duracionTotal
        );
        
        if (!validacion.disponible) {
            clearTimeout(loaderTimeoutId);
            requestAnimationFrame(() => {
            loader.style.display = 'none';
            btnSiguiente.style.display = 'flex';
            });
            
            console.error('Validación fallida:', validacion);
            
            // Mostrar error en el elemento integrado
            if (errorReserva) {
            errorReserva.textContent = validacion.mensaje || "El horario ya no está disponible";
            errorReserva.style.display = 'block';
            }
            return;
        }

        // El especialista puede estar libre, pero el propio cliente puede
        // ya tener otro turno (con otro especialista) que se solape con
        // este horario — eso no lo cubre la validación anterior.
        const conflictoPropio = await verificarConflictoTurnoPropio(
            datosReserva.fecha,
            datosReserva.horario,
            duracionTotal
        );

        if (conflictoPropio) {
            clearTimeout(loaderTimeoutId);
            requestAnimationFrame(() => {
            loader.style.display = 'none';
            btnSiguiente.style.display = 'flex';
            });

            if (errorReserva) {
            errorReserva.textContent = `Ya tenés un turno reservado ese día a las ${conflictoPropio.horarioInicio}hs. No podés tener dos turnos en el mismo horario.`;
            errorReserva.style.display = 'block';
            }
            return;
        }

        // DEBUG: Verificar la estructura de datosReserva.especialistas

        const especialistasPorCategoria = obtenerEspecialistasPorCategoria();

        const serviciosIds = datosReserva.servicios.map(s => s.id);
        
        const turnoData = {
            cliente: {
                nombre: datosReserva.nombre,
                email: datosReserva.email,
                telefono: datosReserva.telefono
            },
            serviciosIds: datosReserva.servicios.map(s => s.id), // ✅ Asegurar que esto sea un array de IDs
            fecha: datosReserva.fecha,
            horarioInicio: datosReserva.horario,
            duracionTotal: duracionTotal,
            montoTotal: calcularSubtotal(),
            señaAbonada: datosReserva.reserva,
            observaciones: datosReserva.observacion || '',
            userId: usuarioActual ? usuarioActual.uid : null,
            // guardarTurno (firestore.js) decide el estado inicial real
            // según esto: si el negocio no cobra seña online, el turno
            // queda confirmado de una — no hay ningún paso de aprobación
            // pendiente. Si cobra, crearPreferenciaPago lo pisa enseguida
            // con 'pendiente_pago' de todos modos (esto es solo la mejor
            // estimación mientras tanto, no la autoridad real).
            pagoOnlineActivo: !!datosReserva.configuracion?.pagoOnlineActivo,
            especialistasPorCategoria: especialistasPorCategoria,
            especialistaIds: datosReserva.especialistas.map(esp => esp.id)
            };

        // DEBUG: Verificar el objeto turnoData antes de guardar

        // Guardar en Firestore
        const turnoGuardado = await firestoreSeguro.guardarTurno(turnoData);

        // Si este negocio cobra la seña online (Mercado Pago), acá se
        // corta el flujo de siempre: no se manda el email ni se muestra
        // la confirmación todavía — eso pasa recién cuando Mercado Pago
        // confirme el pago (ver notificarPagoMP en functions/index.js y
        // el manejo de la vuelta en el DOMContentLoaded de este archivo).
        // demopro puede tener pagoOnlineActivo:true (a modo de prueba, para
        // poder probar el circuito de crédito por cancelación) y sí entra
        // acá en ese caso — pero crearPreferenciaPago nunca llega a
        // contactar a Mercado Pago para demopro, cobre lo que cobre.
        if (datosReserva.configuracion?.pagoOnlineActivo) {
            try {
                const resultadoPago = await window.crearPreferenciaPago({ turnoId: turnoGuardado.id });
                if (resultadoPago.cubiertoPorCredito) {
                    // El crédito de una cancelación anterior cubrió toda la
                    // seña — el turno ya quedó confirmado y el email ya se
                    // mandó del lado del servidor, no hace falta ir a
                    // Mercado Pago ni mandar otro email acá.
                    clearTimeout(loaderTimeoutId);
                    loader.style.display = 'none';
                    mostrarConfirmacion(true);
                    return;
                }
                window.location.href = resultadoPago.initPoint;
                return; // la página se va a Mercado Pago
            } catch (error) {
                console.error('Error iniciando el pago de la seña:', error);
                clearTimeout(loaderTimeoutId);
                requestAnimationFrame(() => {
                    loader.style.display = 'none';
                    btnSiguiente.style.display = 'flex';
                });
                if (errorReserva) {
                    errorReserva.textContent = 'Tu turno quedó reservado, pero no pudimos iniciar el pago de la seña. Volvé a intentar en unos segundos.';
                    errorReserva.style.display = 'block';
                }
                return;
            }
        }

        if (turnoGuardado) {
            try {
                await firebase.functions().httpsCallable('enviarEmailConfirmacion')({ turnoId: turnoGuardado.id });
            } catch (error) {
                console.error('Error al enviar email:', error);
                // No impedir la reserva aunque falle el email
            }
        }

        // Ocultar loader despues de reserva exitosa
        clearTimeout(loaderTimeoutId);
        loader.style.display = 'none';
        
        // Mostrar confirmación de éxito
        mostrarConfirmacion(true);
        
        } catch (error) {
        console.error('Error al reservar:', error);
        // Restaurar UI si hay error
        clearTimeout(loaderTimeoutId);
        requestAnimationFrame(() => {
            loader.style.display = 'none';
            btnSiguiente.style.display = 'flex';
        });
        
        // Mostrar error en el elemento integrado
        if (errorReserva) {
            errorReserva.textContent = 'Ocurrió un error al procesar la reserva. Por favor, intenta nuevamente.';
            errorReserva.style.display = 'block';
        }
        } finally {
            reservaEnProceso = false;
        }
    }
}

// Decide cuál de los tres estados del paso 6 (.exito/.error/.confirmando)
