// Se dispara al volver de Mercado Pago (back_urls armadas en
// crearPreferenciaPago, functions/index.js). Como la redirección completa
// de página borra todo el estado en memoria (datosReserva, pasoActual),
// esto reconstruye lo que hay que mostrar desde cero, con una lectura en
// TIEMPO REAL del turno — no una lectura única, porque el redirect de MP
// puede llegar antes de que el webhook termine de procesar el pago.
function manejarVueltaDeMercadoPago() {
    const params = new URLSearchParams(window.location.search);
    const turnoId = params.get('turnoId');
    const pago = params.get('pago');
    if (!turnoId || pago !== 'retorno') return;

    // Limpiar la URL ya — así un refresh manual no vuelve a disparar esto.
    history.replaceState({}, '', window.location.pathname);

    mostrarConfirmandoPago();

    let unsubscribe = null;
    let avisoTardanzaId = null;

    const empezarAEscuchar = () => {
        unsubscribe = db.collection('turnos').doc(turnoId).onSnapshot((doc) => {
            if (!doc.exists) {
                // El webhook lo borró: pago rechazado o cancelado.
                if (avisoTardanzaId) clearTimeout(avisoTardanzaId);
                if (unsubscribe) unsubscribe();
                mostrarErrorPago('El pago no se pudo procesar y el horario se liberó. Podés intentar reservarlo de nuevo.');
                return;
            }

            const turno = doc.data();
            if (turno.pagoSenia?.estado === 'aprobado') {
                if (avisoTardanzaId) clearTimeout(avisoTardanzaId);
                if (unsubscribe) unsubscribe();
                mostrarConfirmacion(turno.cliente?.nombre);
            }
            // Si sigue 'pendiente', seguimos esperando (ver el aviso de
            // tardanza más abajo) — puede resolver en cualquier momento.
        }, (error) => {
            console.error('Error escuchando el estado del pago:', error);
        });

        // Si tarda demasiado, avisar sin dejar de escuchar (el webhook
        // puede resolver más tarde igual, por ejemplo tras un reintento).
        avisoTardanzaId = setTimeout(() => {
            const p = document.querySelector('.paso-6 .confirmando p');
            if (p) p.textContent = 'Está tardando más de lo habitual — te va a llegar un email en cuanto se confirme.';
        }, 20000);
    };

    if (usuarioActual) {
        empezarAEscuchar();
    } else {
        // La sesión de Firebase Auth persiste entre la ida y la vuelta a
        // Mercado Pago, pero onAuthStateChanged todavía puede no haber
        // resuelto en este primer instante de carga de la página.
        const unsubscribeAuth = firebase.auth().onAuthStateChanged((user) => {
            unsubscribeAuth();
            if (user) {
                empezarAEscuchar();
            } else {
                mostrarErrorPago('No pudimos verificar tu sesión. Iniciá sesión de nuevo y revisá "Mis turnos" para ver el estado de tu pago.');
            }
        });
    }
}

