// Función para geocodificar una dirección
function geocodificarDireccion(direccion, callback) {
    if (typeof google === 'undefined' || !google.maps || !google.maps.Geocoder) {
        console.error("API de Google Maps no está disponible");
        callback("API de Google Maps no está disponible", null);
        return;
    }

    const geocoder = new google.maps.Geocoder();
    geocoder.geocode({ address: direccion }, (results, status) => {
        if (status === 'OK') {
            const location = results[0].geometry.location;
            callback(null, { lat: location.lat(), lng: location.lng() });
        } else {
            callback('Error en geocodificación: ' + status, null);
        }
    });
}

// Función para inicializar los mapas en las direcciones
function inicializarMapasEnDirecciones() {
    const elementoDireccion = document.getElementById('local-direccion');
    if (!elementoDireccion) return;

    const direccion = elementoDireccion.textContent;
    if (!direccion || direccion === "Dirección no disponible") return;

    // Obtener coordenadas desde datosGenerales
    const empresa = datosGenerales.empresa || {};
    const coordenadas = empresa.coordenadas;

    // Crear el popup si no existe
    let popup = elementoDireccion.querySelector('.mapa-popup');
    if (!popup) {
        popup = document.createElement('div');
        popup.className = 'mapa-popup';
        elementoDireccion.appendChild(popup);
    }

    // Usar las coordenadas de la base de datos si están disponibles
    if (coordenadas && coordenadas.lat && coordenadas.lng) {
        coordenadasLocal = coordenadas;

        // Construir URL de mapa estático (reemplaza con tu API key real)
        const apiKey = 'AIzaSyCAO4m-WpFO7Hc9rf8Iy1-gyDMlSLDFong'; // ← Reemplaza con tu clave API
        const urlMapaEstatico = `https://maps.googleapis.com/maps/api/staticmap?center=${coordenadas.lat},${coordenadas.lng}&zoom=16&size=300x200&markers=color:red%7C${coordenadas.lat},${coordenadas.lng}&key=${apiKey}`;

        // Crear imagen del mapa
        const imgMapa = document.createElement('img');
        imgMapa.src = urlMapaEstatico;
        imgMapa.alt = 'Mapa del local';
        imgMapa.style.width = '100%';
        imgMapa.style.height = '100%';
        imgMapa.onload = function() {
        };
        imgMapa.onerror = function() {
            console.error('Error al cargar la imagen del mapa');
            popup.innerHTML = '<div style="padding: 20px; text-align: center;">Error al cargar el mapa</div>';
        };
        
        popup.innerHTML = '';
        popup.appendChild(imgMapa);
    } else {
        // Fallback: geocodificación si no hay coordenadas en la base de datos
        popup.innerHTML = '<div style="padding: 20px; text-align: center;">Cargando mapa...</div>';

        geocodificarDireccion(direccion, (error, coordenadasGeocodificadas) => {
            if (error) {
                console.error('Error en geocodificación:', error);
                popup.innerHTML = '<div style="padding: 20px; text-align: center;">Error al cargar el mapa</div>';
                return;
            }

            coordenadasLocal = coordenadasGeocodificadas;
            const apiKey = 'TU_API_KEY_REAL'; // ← Reemplaza con tu clave API
            const urlMapaEstatico = `https://maps.googleapis.com/maps/api/staticmap?center=${coordenadasGeocodificadas.lat},${coordenadasGeocodificadas.lng}&zoom=16&size=300x200&markers=color:red%7C${coordenadasGeocodificadas.lat},${coordenadasGeocodificadas.lng}&key=${apiKey}`;

            const imgMapa = document.createElement('img');
            imgMapa.src = urlMapaEstatico;
            imgMapa.alt = 'Mapa del local';
            imgMapa.style.width = '100%';
            imgMapa.style.height = '100%';
            popup.innerHTML = '';
            popup.appendChild(imgMapa);
        });
    }

    // Al hacer clic, abrir Google Maps en una nueva pestaña
    elementoDireccion.addEventListener('click', (e) => {
        e.preventDefault();
        if (coordenadasLocal) {
            const urlMaps = `https://www.google.com/maps/search/?api=1&query=${coordenadasLocal.lat},${coordenadasLocal.lng}`;
            window.open(urlMaps, '_blank');
        } else {
            // Fallback: buscar por dirección si no hay coordenadas
            const urlMaps = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(direccion)}`;
            window.open(urlMaps, '_blank');
        }
    });
}

