const cache = {
    config: null,
    categorias: null,
    servicios: null,
    especialistas: {},
    horarios: {},
    horarios_multi: {}, // ✅ AGREGAR: Cache para horarios múltiples
    timestamp: {
        config: 0,
        categorias: 0,
        servicios: 0,
        especialistas: {},
        horarios: {},
        horarios_multi: {} // ✅ AGREGAR: Timestamp para horarios múltiples
    },
    
    // Tiempo de vida del caché en milisegundos (5 minutos)
    ttl: 5 * 60 * 1000,
    
    // Verificar si el caché es válido
    esValido: function(clave, idEspecifico = null) {
        try {
            const timestamp = idEspecifico 
                ? this.timestamp[clave]?.[idEspecifico] || 0
                : this.timestamp[clave] || 0;
            
            return (Date.now() - timestamp) < this.ttl;
        } catch (error) {
            console.warn('Error validando caché:', error);
            return false;
        }
    },
    
    // Guardar en caché
    guardar: function(clave, datos, idEspecifico = null) {
        try {
            // ✅ CORRECCIÓN: Validar que los datos no sean null/undefined
            if (datos === null || datos === undefined) {
                console.warn(`⚠️ Intentando guardar datos inválidos en caché: ${clave}`, datos);
                return;
            }

            if (idEspecifico) {
                if (!this[clave]) this[clave] = {};
                if (!this.timestamp[clave]) this.timestamp[clave] = {};
                
                this[clave][idEspecifico] = datos;
                this.timestamp[clave][idEspecifico] = Date.now();
            } else {
                this[clave] = datos;
                this.timestamp[clave] = Date.now();
            }
            
        } catch (error) {
            console.error('Error guardando en caché:', error);
        }
    },
    
    // Obtener del caché
    obtener: function(clave, idEspecifico = null) {
        try {
            const datos = idEspecifico 
                ? this[clave]?.[idEspecifico] ?? null
                : this[clave] ?? null;
            
            if (datos !== null && this.esValido(clave, idEspecifico)) {
                cacheMonitor.incrementHit();
                cacheMonitor.savings += this.estimarLecturasAhorradas(clave);
                return datos;
            }
            
            cacheMonitor.incrementMiss();
            return null;
        } catch (error) {
            console.error('Error obteniendo del caché:', error);
            cacheMonitor.incrementMiss();
            return null;
        }
    },
    
    estimarLecturasAhorradas: function(clave) {
        // Estimación de documentos leídos por operación
        const estimaciones = {
            config: 1,
            categorias: 10, // Suponiendo 10 categorías
            servicios: 50,  // Suponiendo 50 servicios
            especialistas: 5, // Por categoría
            horarios: 1,    // Por especialista por fecha
            horarios_multi: 3 // Múltiples especialistas
        };
        return estimaciones[clave] || 1;
    },

    // ✅ NUEVA FUNCIÓN: Limpiar caché específico
    limpiarEspecifico: function(clave, idEspecifico = null) {
        try {
            if (idEspecifico) {
                if (this[clave] && this[clave][idEspecifico]) {
                    delete this[clave][idEspecifico];
                }
                if (this.timestamp[clave] && this.timestamp[clave][idEspecifico]) {
                    delete this.timestamp[clave][idEspecifico];
                }
            } else {
                this[clave] = null;
                this.timestamp[clave] = 0;
            }
        } catch (error) {
            console.error('Error limpiando caché específico:', error);
        }
    },

};

// Estrategia de precaching - Cargar datos esenciales al inicio
async function precacheDatosEsenciales() {
    try {
        
        // Cargar configuración, categorías y servicios en paralelo
        await Promise.allSettled([
            firestoreSeguro.obtenerConfiguracion(),
            firestoreSeguro.obtenerCategorias(),
            firestoreSeguro.obtenerServicios()
        ]);
        
    } catch (error) {
        console.warn('⚠️ Precaching falló:', error);
    }
}

// Guardar cache antes de recargar/cerrar
window.addEventListener('beforeunload', guardarCacheEnStorage);

// Cargar al iniciar
document.addEventListener('DOMContentLoaded', cargarCacheDesdeStorage);

// Función para limpiar caché cuando sea necesario
function limpiarCache(clave = null) {
    if (clave) {
        cache[clave] = null;
        cache.timestamp[clave] = 0;
    } else {
        // Limpiar todo el caché
        Object.keys(cache).forEach(key => {
            if (key !== 'ttl' && key !== 'timestamp') {
                cache[key] = key === 'especialistas' || key === 'horarios' || key === 'horarios_multi' ? {} : null;
            }
        });
        Object.keys(cache.timestamp).forEach(key => {
            cache.timestamp[key] = key === 'especialistas' || key === 'horarios' || key === 'horarios_multi' ? {} : 0;
        });
    }
}


// Sistema de caché en localStorage
function guardarCacheEnStorage() {
    try {
        const cacheData = {
            config: cache.config,
            categorias: cache.categorias,
            servicios: cache.servicios,
            timestamp: cache.timestamp,
            fechaGuardado: Date.now()
        };
        localStorage.setItem('firestoreCache', JSON.stringify(cacheData));
    } catch (error) {
        console.warn('No se pudo guardar el caché:', error);
    }
}

function cargarCacheDesdeStorage() {
    try {
        const cacheData = localStorage.getItem('firestoreCache');
        if (cacheData) {
            const parsed = JSON.parse(cacheData);
            const unaHora = 60 * 60 * 1000; // 1 hora en milisegundos
            
            // Solo cargar si tiene menos de 1 hora
            if (Date.now() - parsed.fechaGuardado < unaHora) {
                cache.config = parsed.config;
                cache.categorias = parsed.categorias;
                cache.servicios = parsed.servicios;
                cache.timestamp = parsed.timestamp;
            } else {
                localStorage.removeItem('firestoreCache');
            }
        }
    } catch (error) {
        console.warn('Error cargando caché:', error);
    }
}
